/** SVG pronto pra injetar. A cor vem do CSS, via `currentColor`. */
export function iconSvg(name) {
  const icon = ICONS[name];
  if (!icon) return '';

  const paths = icon.paths
    .map((d) => `<path fill="currentColor" d="${d}"/>`)
    .join('');
  return `<svg viewBox="${icon.viewBox}" aria-hidden="true">${paths}</svg>`;
}

